ion.","alternatives":[{"id":"01a2190a-ae84-7fe5-ad64-f6dde4b33984","description":"Refraction","correct_answer":true},{"id":"01a2190a-ae84-7b13-a193-c35fe9a2ba31","description":"Reflection","correct_answer":false},{"id":"01a2190a-ae84-706d-8f22-66b36da639b0","description":"Convection","correct_answer":false},{"id":"01a2190a-ae84-720b-a638-78ef79d597b4","description":"Ablation","correct_answer":false}]},{"id":"01a2190a-ae84-7aa0-90bf-001608f5f431","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which substance takes its name from the Greek for `not flammable\'?","difficulty":2,"explanation":"Asbestos fibers were used in insulation and other heat-resistant materials, but inhaling them can cause serious disease.","alternatives":[{"id":"01a2190a-ae84-7ccb-adbe-2f19fdc59e36","description":"Asbestos","correct_answer":true},{"id":"01a2190a-ae84-704b-8032-a63cf8210c76","description":"Bleach","correct_answer":false},{"id":"01a2190a-ae84-79bf-8345-a9150dfe08da","description":"Ethanol","correct_answer":false},{"id":"01a2190a-ae84-7a60-8e72-8a6c05dded94","description":"Methadone","correct_answer":false}]},{"id":"01a2190a-ae84-78a6-83d7-df89a39715e1","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"In mammals, which organ produces milk?","difficulty":2,"explanation":"Mammary glands are modified sweat glands, and prolactin helps stimulate milk production after birth.","alternatives":[{"id":"01a2190a-ae84-7bc8-a1e3-9f8d25e92722","description":"Mammary gland","correct_answer":true},{"id":"01a2190a-ae84-7840-a5d8-ff6de0737e73","description":"Prostate","correct_answer":false},{"id":"01a2190a-ae84-779b-bcd0-e96cd64aa69d","description":"Pancreas","correct_answer":false},{"id":"01a2190a-ae84-7840-946b-eea5defb6858","description":"Pituitary gland","correct_answer":false}]},{"id":"01a2190a-ae84-7644-9157-cc82c7670077","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"Which organisms use gills for breathing?","difficulty":2,"explanation":"Many aquatic 